{
  "root_causes": [
    {
      "service": "ts-travel-service",
      "fault_kind": "network_partition",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT src, c.service_name caller, c.span_name, coalesce(p.service_name,'(none)') callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 p50_ms, max(c.duration)/1e6 max_ms FROM (SELECT 'abn' src, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) c LEFT JOIN (SELECT trace_id, parent_span_id, service_name FROM abnormal_traces WHERE attr_span_kind='Server' UNION ALL SELECT trace_id, parent_span_id, service_name FROM normal_traces WHERE attr_span_kind='Server') p ON c.trace_id=p.trace_id AND p.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND c.service_name='ts-travel-service' AND c.span_name='POST' GROUP BY ALL ORDER BY 2,3,1",
          "claim": "ts-travel-service POSTs to ts-seat-service (430 normal) disappear in abnormal; 8 POSTs with no callee span hang about 113 s."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name, c.attr_k8s_pod_name, c.span_name, count(*) n, sum(CASE WHEN p.span_id IS NULL THEN 1 ELSE 0 END) no_server_child, max(c.duration)/1e6 max_ms FROM abnormal_traces c LEFT JOIN abnormal_traces p ON c.trace_id=p.trace_id AND p.parent_span_id=c.span_id AND p.attr_span_kind='Server' WHERE c.attr_span_kind='Client' AND c.service_name='ts-travel-service' AND c.span_name='POST' GROUP BY 1,2,3",
          "claim": "Of 37 abnormal POST clients from ts-travel-service, 8 have no server child and run over 100 s."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND attr_span_kind='Server' GROUP BY 1,2,3",
          "claim": "ts-seat-service still answers its other callers normally, with server p50 around 16 ms, so the seat service itself is alive."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, p.service_name callee_server, count(*) n, approx_quantile(c.duration,0.5)/1e6 client_p50_ms, approx_quantile(p.duration,0.5)/1e6 server_p50_ms, max(c.duration)/1e6 client_max_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND p.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND p.attr_span_kind='Server' AND c.service_name='ts-route-plan-service' AND p.service_name='ts-travel-service' GROUP BY 1,2",
          "claim": "ts-route-plan-service calls into ts-travel-service take up to about 131 s, because travel-service's downstream seat call hangs."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, p.service_name callee_server, count(*) n, approx_quantile(c.duration,0.5)/1e6 client_p50_ms, max(c.duration)/1e6 client_max_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND p.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND p.attr_span_kind='Server' AND c.service_name='ts-travel-plan-service' AND p.service_name='ts-route-plan-service' GROUP BY 1,2",
          "claim": "ts-travel-plan-service calls to ts-route-plan-service rise to about 131 s in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms, max(duration)/1e6 max_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%travelPlan%' GROUP BY 1,2",
          "claim": "ts-ui-dashboard travelPlan requests reach 20 s or more, matching the slow travel-plan chain behind them."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, p.service_name callee_server, count(*) n, approx_quantile(p.duration,0.95)/1e6 callee_p95_ms, avg(CASE WHEN p.attr_status_code='Error' THEN 1 ELSE 0 END) err FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND p.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND p.attr_span_kind='Server' AND c.service_name='ts-ui-dashboard' AND p.service_name='ts-travel-service' GROUP BY 1,2",
          "claim": "ts-ui-dashboard calls to ts-travel-service show elevated p95 latency and a non-zero error share in the abnormal period."
        }
      ]
    }
  ]
}
